const int BARREL_ITER = 40;
const float BARREL_AMP = 0.05;
const vec4 COLOR_LIFT = vec4(-0.03, 0.01, 0.05, 0.0);
const vec4 COLOR_GAMMA = vec4(-0.02, 0.02, -0.01, 0.0);
const vec4 COLOR_GAIN = vec4(1.04, 0.98, 1.02, 1.0);

const float PI = acos(-1.0);
const float SQRT2 = sqrt(2.0);
const float INV_SQRT2 = 1.0 / SQRT2;
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

#define saturate(x) clamp(x, 0.0, 1.0)

// http://www.jcgt.org/published/0009/03/02/
uvec3 hash3u(uvec3 v) {
  v = v * 1664525u + 1013904223u;

  v.x += v.y * v.z;
  v.y += v.z * v.x;
  v.z += v.x * v.y;

  v ^= v >> 16u;

  v.x += v.y * v.z;
  v.y += v.z * v.x;
  v.z += v.x * v.y;

  return v;
}

vec3 hash3f(vec3 v) {
  uvec3 r = floatBitsToUint(v);
  return vec3(hash3u(r)) / float(-1u);
}

uvec3 seed;
vec3 random3() {
  seed = hash3u(seed);
  return vec3(seed) / float(-1u);
}

vec3 grad(float phase) {
  return saturate(
    1.0 - 3.0 * abs(vec3(0.25, 0.5, 0.75) - phase)
  ) * 4.0 / float(BARREL_ITER);
}

vec2 barrelUv(vec2 uv, float amp) {
  const float CORN = 0.5 * SQRT2;

  float a = min(3.0 * sqrt(amp), INV_SQRT2 * PI);
  float zoom = INV_SQRT2 / (tan(INV_SQRT2 * a) + INV_SQRT2);

  vec2 uvt = uv - 0.5;
  return saturate(mix(
    vec2(0.5),
    uv + normalize(uvt) * tan(length(uvt) * a),
    zoom
  ));
}

vec3 RRTAndODTFit(vec3 v) {
  vec3 a = v * (v + 0.0245786) - 0.000090537;
  vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081;
  return a / b;
}

vec3 tonemapACESHill(vec3 sRGB) {
  vec3 inputCol = mat3(
    0.59719, 0.07600, 0.02840,
    0.35458, 0.90834, 0.13383,
    0.04823, 0.01566, 0.83777
  ) * sRGB;
  vec3 fittedCol = RRTAndODTFit(inputCol);
  vec3 outputCol = mat3(
    1.60475, -0.10208, -0.00327,
    -0.53108, 1.10813, -0.07276,
    -0.07367, -0.00605, 1.07602
  ) * fittedCol;
  return saturate(outputCol);
}

vec3 sRGBOETF(vec3 x) {
  vec3 x_ = saturate(x);
  return mix(
    x_ * 12.92,
    pow(x_, vec3(0.4167)) * 1.055 - 0.055,
    step(0.0031308, x_)
  );
}

vec3 liftGammaGain(vec3 rgb) {
  vec4 liftt = 1.0 - pow(1.0 - COLOR_LIFT, log2(COLOR_GAIN + 1.0));

  vec4 gammat = COLOR_GAMMA.rgba - vec4(0.0, 0.0, 0.0, dot(LUMA, COLOR_GAMMA.rgb));
  vec4 gammatTemp = 1.0 + 4.0 * abs(gammat);
  gammat = mix(gammatTemp, 1.0 / gammatTemp, step(0.0, gammat));

  vec3 col = rgb;
  float luma = dot(LUMA, col);

  col = pow(col, gammat.rgb);
  col *= pow(COLOR_GAIN.rgb, gammat.rgb);
  col = max(mix(2.0 * liftt.rgb, vec3(1.0), col), 0.0);

  luma = pow(luma, gammat.a);
  luma *= pow(COLOR_GAIN.a, gammat.a);
  luma = max(mix(2.0 * liftt.a, 1.0, luma), 0.0);

  col += luma - dot(LUMA, col);

  return saturate(col);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  seed = uvec3(fragCoord, iFrame);

  vec2 uv = fragCoord.xy / iResolution.xy;
  vec2 p = uv * 2.0 - 1.0;
  p.x *= iResolution.x / iResolution.y;

  vec3 col = vec3(0.0);

  for (int i = 0; i < BARREL_ITER; i ++) {
    float phase = (float(i) + random3().x) / float(BARREL_ITER);
    vec3 tint = grad(phase);
    vec2 uv = barrelUv(uv, BARREL_AMP * phase);
    col += tint * texture(iChannel0, uv).xyz;
  }

  col *= 1.0 - 0.2 * length(p);
  col = tonemapACESHill(max(col, 0.0));
  col = sRGBOETF(col);
  col = liftGammaGain(col);

  fragColor = vec4(col, 1.0);
}

const int MARCH_ITER = 80;
const float ROUGHNESS = 0.1;
const float DOF_FOCAL_LENGTH = 1.5;
const float DOF_SIZE = 0.01;
const float FOG_NEAR = 2.0;
const float FOG_FAR = 6.0;

const float PI = acos(-1.0);
const float TAU = 2.0 * PI;
const float INV_PI = 1.0 / PI;

#define saturate(x) clamp(x, 0.0, 1.0)
#define lofi(x, d) (floor((x) / (d)) * (d))

// http://www.jcgt.org/published/0009/03/02/
uvec3 hash3u(uvec3 v) {
  v = v * 1664525u + 1013904223u;

  v.x += v.y * v.z;
  v.y += v.z * v.x;
  v.z += v.x * v.y;

  v ^= v >> 16u;

  v.x += v.y * v.z;
  v.y += v.z * v.x;
  v.z += v.x * v.y;

  return v;
}

vec3 hash3f(vec3 v) {
  uvec3 r = floatBitsToUint(v);
  return vec3(hash3u(r)) / float(-1u);
}

vec2 cis(float t) {
  return vec2(cos(t), sin(t));
}

vec2 uniformCircle(vec2 Xi) {
  float phi = TAU * Xi.x;
  return sqrt(Xi.y) * cis(phi);
}

float smin(float a, float b, float k) {
  float h = max(k - abs(a - b), 0.0) / k;
  return min(a, b) - h * h * h * k / 6.0;
}

mat2 rotate2D(float t) {
  float c = cos(t);
  float s = sin(t);
  return mat2(c, s, -s, c);
}

mat3 orthBas(vec3 z) {
  z = normalize(z);
  vec3 up = abs(z.y) < 0.99 ? vec3(0.0, 1.0, 0.0) : vec3(0.0, 0.0, 1.0);
  vec3 x = normalize(cross(up, z));
  return mat3(x, cross(z, x), z);
}

vec3 cyclic(vec3 p) {
  vec4 sum = vec4(0);
  mat3 rot = orthBas(vec3(2, -3, 1));

  for (int i = 0; i < 5; i++) {
    p *= rot;
    p += sin(p.zxy);
    sum += vec4(cross(cos(p), sin(p.yzx)), 1);
    sum /= 0.5;
    p *= 2.0;
  }

  return sum.xyz / sum.w;
}

float sdtorus( vec3 p, float R, float r ) {
  vec2 pt = vec2( length( p.xy ) - R, p.z );
  return length( pt ) - r;
}

float sdbox(vec2 p, vec2 s) {
  vec2 d = abs(p) - s;
  return min(max(d.x, d.y), 0.0) + length(max(d, 0.0));
}

float sdbox(vec3 p, vec3 s) {
  vec3 d = abs(p) - s;
  return min(max(max(d.x, d.y), d.z), 0.0) + length(max(d, 0.0));
}

float grl;

float thicknessFn(float t) {
  return (
    0.07
    + min(0.0, 0.5 * (grl - 1.0))
    + 0.01 * pow(0.5 * cos(t) + 0.5, 5.0)
  );
}

float sdtorusmetal(vec3 p) {
  float t = atan(p.y, p.x);
  return sdtorus(p, 0.375, thicknessFn(24.0 * t));
}

float sdcylindermetal(vec3 p, float l) {
  return sdbox(vec2(length(p.xy), p.z), vec2(thicknessFn(8.0 * TAU * p.z), l));
}

vec3 gcell;

vec4 map(vec3 p) {
  vec3 pt = p - gcell;
  vec3 dice = hash3f(gcell);
  pt.yz *= rotate2D(TAU * lofi(dice.x, 0.25));
  pt.zx *= rotate2D(TAU * lofi(dice.y, 0.25));
  pt.xy *= rotate2D(TAU * lofi(dice.z, 0.25));

  vec3 dice2 = hash3f(gcell + 0.5);

  float dbound = sdbox(pt, vec3(0.5));
  float dbound2 = sdbox(pt, vec3(0.375));

  float d1 = mix(sdtorusmetal(pt - vec3(0.375, 0.375, 0.0)), 1E9, step(dice2.x, 0.4));
  d1 = min(d1, mix(sdtorusmetal(pt + vec3(0.375, 0.375, 0.0)), 1E9, step(dice2.y, 0.4)));
  d1 = max(d1, dbound2);

  float d2 = sdcylindermetal(pt.yzx, 0.5);
  d2 = min(d2, sdcylindermetal(pt.zxy, 0.5));
  d2 = max(d2, max(dbound, -dbound2));

  float d3 = sdcylindermetal(pt, 0.5);
  d3 = max(d3, mix(-1E9, -dbound2, step(dice2.z, 0.4)));

  return vec4(smin(min(d1, d2), d3, 0.15), 0, 0, 0);
}

float mapForN(vec3 p) {
  vec3 displace = cyclic(16.0 * p);
  displace *= 0.005 * sign(displace) * pow(abs(displace), vec3(3.0));
  p += displace;
  return map(p).x;
}

vec3 nmap(vec3 p, float delta) {
  vec2 d = vec2(0.0, delta);
  return normalize(vec3(
    mapForN(p + d.yxx) - mapForN(p - d.yxx),
    mapForN(p + d.xyx) - mapForN(p - d.xyx),
    mapForN(p + d.xxy) - mapForN(p - d.xxy)
  ));
}

vec4 gridTraversal(vec3 ro, vec3 rd) {
  vec3 cell = floor(ro + rd * 0.01) + 0.5;
  vec3 src = -(ro - cell) / rd;
  vec3 dst = abs(0.5 / rd);
  vec3 bv = src + dst;
  float len = min(bv.x, min(bv.y, bv.z));
  return vec4(cell, len);
}

float dGGX(float dotNH, float roughnessSq) {
  float f = dotNH * dotNH * (roughnessSq - 1.0) + 1.0;
  return roughnessSq / (PI * f * f + 1E-4);
}

float vGGX(float dotNL, float dotNV, float alphaSq) {
  float lambdaV = dotNL * sqrt(mix(dotNV * dotNV, 1.0, alphaSq));
  float lambdaL = dotNV * sqrt(mix(dotNL * dotNL, 1.0, alphaSq));
  return 0.5 / (lambdaV + lambdaL + 1E-4);
}

vec3 fresnelSchlick(float dotVH, vec3 f0, vec3 f90) {
  return mix(f0, f90, pow(1.0 - dotVH, 5.0));
}

vec3 doAnalyticLighting(vec3 L, vec3 V, vec3 N, float roughness, vec3 albedo, vec3 f0) {
  vec3 H = normalize(L + V);

  float dotNL = max(dot(N, L), 1E-3);
  float dotNV = max(dot(N, V), 1E-3);
  float dotNH = max(dot(N, H), 1E-3);
  float dotVH = max(dot(V, H), 1E-3);

  float roughnessSq = roughness * roughness;

  float Vis = vGGX(dotNL, dotNV, roughnessSq);
  float D = dGGX(dotNH, roughnessSq);

  vec3 FSpec = fresnelSchlick(dotVH, f0, vec3(1.0));
  vec3 diffuse = albedo * INV_PI;
  vec3 specular = vec3(Vis * D);

  // is dotNL needed here??
  return dotNL * mix(diffuse, specular, FSpec);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec2 p = uv * 2.0 - 1.0;
  p.x *= iResolution.x / iResolution.y;

  vec3 co = vec3(0.0, 0.0, 4.0);
  vec3 ct = vec3(4.0, 2.0, 0.0);
  co.zx *= rotate2D(0.4 * iTime);
  ct.zx *= rotate2D(0.4 * iTime);
  mat3 cb = orthBas(co - ct);

  vec2 pt = p * rotate2D(0.1 * iTime);
  vec3 ro = co;
  vec3 rd = cb * normalize(vec3(pt, -3.0));
  vec3 rfp = ro + rd * DOF_FOCAL_LENGTH;
  ro += cb * vec3(DOF_SIZE * uniformCircle(hash3f(vec3(p, iTime)).xy), 0.0);
  rd = normalize(rfp - ro);

  float rl = 0.0;
  vec3 rp = ro + rd * rl;
  vec4 isect;

  vec4 grid = gridTraversal(rp, rd);
  float gridl = grid.w;

  for (int i = 0; i < MARCH_ITER; i ++) {
    if (gridl <= rl) {
      rl = gridl;
      rp = ro + rd * rl;
      grid = gridTraversal(rp, rd);
      gridl += grid.w;
    }

    grl = rl;
    gcell = grid.xyz;

    isect = map(rp);
    rl += 0.8 * isect.x;
    rp = ro + rd * rl;
  }

  if (isect.x > 1E-2) {
    fragColor = vec4(0.0, 0.0, 0.0, 1.0);
    return;
  }

  gcell = grid.xyz;
  vec3 N = nmap(rp, 1E-4);
  vec3 N2 = nmap(rp, 1E-2);
  N = mix(N2, clamp(N, -1.0, 1.0), saturate(dot(N, N2)));

  // lighting
  vec3 col = vec3(0.0);
  for (int i = 0; i < 3; i ++) {
    vec3 lightPos = vec3[](
      vec3(2.0, 1.0, 7.0),
      vec3(0.0, -2.0, -5.0),
      vec3(-5.0, 0.0, -1.0)
    )[i];
    vec3 lightCol = vec3[](
      vec3(1000.0),
      vec3(800.0),
      vec3(500.0)
    )[i];

    vec3 L = lightPos - rp;
    float lenL = length(L);
    L = normalize(L);

    float dotNL = max(dot(N, L), 1E-3);

    vec3 albedo = vec3(0.0);
    vec3 f0 = vec3(0.1);
    vec3 irradiance = lightCol * dotNL / lenL / lenL;

    vec3 lightShaded = irradiance;
    lightShaded *= doAnalyticLighting(L, -rd, N, ROUGHNESS, albedo, f0);
    col += lightShaded;
  }

  float fog = smoothstep(FOG_NEAR, FOG_FAR, rl);
  col = mix(col, vec3(0.0), fog);

  fragColor = vec4(col, 1.0);
}
